mapper.sql:
where 1=1

		and cpdv_llave = #{llaveTabla}


		and cpdv_estado = #{estado}


		and dpdv_fecharegistro >= #{fechaRegistroMin}


		and dpdv_fecharegistro  <   #{fechaRegistroMax}


		and dpdv_fecha >= #{fechaMin}


		and dpdv_fecha  <   #{fechaMax}


		and cpdv_funcionario = #{funcionario}


		and cpdv_plantilla = #{plantilla}


		and cpdv_nombre = #{nombre}


		and cpdv_estadoexpediente = #{estadoExpediente}


		and cpdv_textofiltro = #{textoFiltro}


		and cpdv_descripcion = #{descripcion}


		and cpdv_transaccion = #{transaccion}


		and (cpdv_nombre like upper('%' || #{filtroParametro} || '%') or cpdv_textofiltro like '%' || #{filtroParametro} || '%')

mapper.select:

	 where cpdv_estadoexpediente  in (
	 	select cptr_estadopartida from procesotransicion_ptrp where cptr_plantilla = #{plantilla} and cptr_estado ='A' and bptr_documentador = false and cptr_estadopartida is not null) 
	 and cpdv_estado !='I'
 	and dpdv_fecha >= #{fechaMin}
    and dpdv_fecha  <   #{fechaMax}
    and cpdv_nombre = #{nombre}

		and (cpdv_nombre like upper('%' || #{filtroParametro} || '%') or upper(cpdv_textofiltro) like upper('%' || #{filtroParametro} || '%'))

    order by dpdv_fecha desc, cpdv_nombre desc

		select cp.cpvc_documento 
		from pedidoventacaracteristica_pvcp cp
        where cp.cpvc_campo = #{pFilter.campo}
         	and cp.cpvc_estado = 'A' 
			and cp.cpvc_valoropcion = #{pFilter.valorOpcion}

mapper.sql:
		order by nombre descdescripcion desc, nombre descfecha desc, nombre desc
  		LIMIT #{dto.paginacionRegistroFinal}
		OFFSET #{dto.paginacionRegistroInicial}

select.if:
	select cp_rol.cpvc_valoropcion from usuariorol_erlp 
		inner join pedidoventacaracteristica_pvcp cp_rol on (cp_rol.cpvc_documento = cerl_documento and cp_rol.cpvc_estado = 'A')
 	where cerl_estado = 'A' and cerl_usuario = #{usuario}
 		and cp_rol.cpvc_campo in #{campoRelacion}
 	union
 	select cpvc_documento from pedidoventacaracteristica_pvcp
 		inner join usuariorol_erlp on (cpvc_valoropcion = cerl_documento and cerl_estado = 'A')
 	where cpvc_estado = 'A' and cpvc_campo in #{campoRelacion}
 		and cerl_usuario = #{usuario}
 	union
 	select cpvc_documento from pedidoventacaracteristica_pvcp
 		inner join documentorelacionexpediente_dexp on (cdex_campomaestro = cpvc_llave and cdex_estado = 'A')
 		inner join usuariorol_erlp on (cerl_estado = 'A' and cdex_expedientedetalle = cerl_documento)
 	where cpvc_estado = 'A' and cpvc_campo in #{campoRelacion}
 		and cerl_usuario = #{usuario}
 	union
 	select cdex_expedientedetalle from usuariorol_erlp 
		inner join pedidoventacaracteristica_pvcp cp_rol on (cp_rol.cpvc_documento = cerl_documento and cp_rol.cpvc_estado = 'A')
 		inner join documentorelacionexpediente_dexp dex_rol on (dex_rol.cdex_campomaestro = cp_rol.cpvc_llave and dex_rol.cdex_estado = 'A')
 	where cerl_estado = 'A' and cerl_usuario = #{usuario}
 		and cp_rol.cpvc_campo in #{campoRelacion}

mapper.select:

where cpdv_nombre = #{dto.nombre}
and cpdv_plantilla in (#{item})
LIMIT 1
